    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 25-year-old male presents to the ED after striking his neck on a steering wheel in an MVA. He is hoarse, coughing up blood (hemoptysis), and has pain with swallowing. What is the classic triad of laryngeal trauma symptoms?', '["Fever, drooling, and muffled voice", "Hoarseness, dyspnea (stridor), and hemoptysis", "Neck mass, ear pain, and weight loss", "Cough, wheezing, and chest pain", "Neck pain, headache, and dizziness"]'::jsonb, 1, 'The classic triad of laryngeal trauma is hoarseness, dyspnea, and hemoptysis. Any patient presenting with these after a neck injury requires immediate airway evaluation.'),
    (v_topic_id, 'On physical examination of the patient with blunt neck trauma, the physician notes palpable crepitus (subcutaneous emphysema) over the anterior neck. What does this specific finding strongly indicate?', '["A fractured cervical spine", "A violation or tear of the mucosal airway, allowing air to escape into the soft tissues", "A ruptured carotid artery", "A vocal cord polyp", "A hematoma of the thyroid gland"]'::jsonb, 1, 'Subcutaneous emphysema in the setting of neck trauma is a red flag for an airway tear (e.g., laryngeal or tracheal mucosal laceration) or an esophageal tear.'),
    (v_topic_id, 'A patient with severe blunt laryngeal trauma and palpable crepitus is in respiratory distress. Why is "blind" or forceful oral endotracheal intubation absolutely contraindicated?', '["It is too painful", "The endotracheal tube can easily pass through the mucosal tear into a false passage, completely obliterating the remaining airway", "It causes vocal cord paralysis", "It spreads infection", "It causes a heart attack"]'::jsonb, 1, 'Blind intubation can turn a partial airway tear into a complete transection. The airway must be secured under direct vision (awake fiberoptic intubation) or via an awake tracheostomy/cricothyrotomy under local anesthesia.'),
    (v_topic_id, 'A 30-year-old male suffered a "clothesline" injury while riding a dirt bike. He has loss of the normal thyroid cartilage prominence (loss of the "Adam''s apple"). What does this finding suggest?', '["Normal anatomy", "A massively displaced, comminuted fracture of the thyroid cartilage", "A dislocated shoulder", "A fractured hyoid bone", "A swollen epiglottis"]'::jsonb, 1, 'Loss of the normal thyroid eminence implies a severe, crushing, anterior-to-posterior fracture of the thyroid cartilage, often requiring open surgical reduction and internal fixation (ORIF).'),
    (v_topic_id, 'What is the most appropriate imaging modality to evaluate the cartilaginous framework of the larynx in a stable patient following blunt neck trauma?', '["Plain AP neck X-ray", "Ultrasound of the neck", "High-resolution CT scan of the neck with contrast", "MRI of the neck", "PET scan"]'::jsonb, 2, 'A CT scan provides excellent detail of the laryngeal cartilages (to identify fractures/displacements) and the soft tissues (to identify hematomas or air tracking).'),
    (v_topic_id, 'If a patient sustains a displaced fracture of the thyroid cartilage with exposed cartilage in the airway lumen, what is the primary goal of surgical exploration and repair?', '["To remove the entire larynx", "To carefully re-approximate the mucosa over the exposed cartilage and rigidly fix the fractured cartilages to prevent permanent airway stenosis and preserve voice", "To inject Botox into the vocal cords", "To place a permanent metal stent", "To remove the vocal folds"]'::jsonb, 1, 'Exposed cartilage in the airway rapidly becomes infected and heals with massive fibrotic scarring. Early open reduction and mucosal repair (within 24-48 hours) prevents lifelong airway crippling.'),
    (v_topic_id, 'A 45-year-old female presents with progressively worsening shortness of breath and biphasic stridor over the last 3 months. Her voice is relatively normal. She has a history of a severe motor vehicle accident 6 months ago requiring 3 weeks of intubation in the ICU. What is the most likely diagnosis?', '["Asthma", "Bilateral vocal fold paralysis", "Acquired subglottic stenosis", "Laryngeal cancer", "Vocal fold nodules"]'::jsonb, 2, 'Prolonged endotracheal intubation is the leading cause of acquired subglottic stenosis in adults. The cuff pressure causes ischemia and scarring of the complete cricoid ring.'),
    (v_topic_id, 'Why does subglottic stenosis typically present with dyspnea and biphasic stridor, but a relatively normal or only mildly affected voice?', '["The subglottis is primarily responsible for breathing, while the true vocal folds (which are usually spared) are responsible for voice", "The vocal cords vibrate louder to compensate", "The epiglottis covers the stenosis", "The nerves are hyperactive", "The patient is whispering"]'::jsonb, 0, 'Because the scarring is below the level of the true vocal folds, glottic closure and vibration are often intact, preserving the voice while the airway below is choked off.'),
    (v_topic_id, 'For a mature, dense, severe (Cotton-Myer Grade III/IV) acquired subglottic stenosis in an adult, what is the most definitive surgical treatment to achieve decannulation?', '["Repeated laser incisions and balloon dilations forever", "Cricotracheal resection (CTR) – resecting the scarred segment and anastomosing the healthy trachea to the cricoid/thyroid cartilage", "Total laryngectomy", "Tracheostomy for life", "Botox injections"]'::jsonb, 1, 'While early or soft strictures may respond to dilation, mature fibrotic or cartilaginous strictures require complete surgical excision of the scar and primary anastomosis for a definitive cure.'),
    (v_topic_id, 'A 55-year-old glassblower presents with a painless, intermittent swelling on the right side of his neck. The swelling enlarges when he blows glass (Valsalva maneuver) and he frequently notes a gurgling sound. Laryngoscopy shows a smooth bulge in the right false vocal fold. What is the diagnosis?', '["Branchial cleft cyst", "External Laryngocele", "Thyroid nodule", "Squamous cell carcinoma", "Parotid tumor"]'::jsonb, 1, 'A laryngocele is an abnormal, air-filled dilation of the laryngeal saccule. It inflates with increased intraluminal pressure (like glassblowing or playing a wind instrument).'),
    (v_topic_id, 'What anatomic structure does an "external" laryngocele herniate through to present as a lateral neck mass?', '["The cricothyroid membrane", "The thyrohyoid membrane", "The quadrangular membrane", "The conus elasticus", "The strap muscles"]'::jsonb, 1, 'An external laryngocele extends superiorly from the laryngeal ventricle and pokes out through the thyrohyoid membrane, presenting as a compressible mass in the lateral neck.'),
    (v_topic_id, 'If an adult presents with a new, spontaneous laryngocele and no history of occupational Valsalva, what critical underlying pathology MUST be explicitly ruled out via endoscopy or imaging?', '["A viral infection", "An underlying laryngeal Squamous Cell Carcinoma obstructing the neck of the saccule in the ventricle, acting like a one-way valve", "A vocal fold nodule", "Asthma", "Acid reflux"]'::jsonb, 1, 'A small, hidden cancer in the laryngeal ventricle can trap air in the saccule, causing it to dilate. All new adult laryngoceles require careful evaluation to rule out malignancy.'),
    (v_topic_id, 'A 65-year-old male presents with a long history of slowly progressive hoarseness and a hard, non-tender mass palpable over his cricoid cartilage on the outside of his neck. Laryngoscopy shows a smooth, submucosal bulge in the subglottis. CT shows a mass arising from the cricoid with "popcorn" calcifications. What is the most likely diagnosis?', '["Chondroma or low-grade Chondrosarcoma of the larynx", "Squamous cell carcinoma", "Laryngocele", "Thyroid goiter", "Hemangioma"]'::jsonb, 0, 'Chondrosarcomas of the larynx typically arise from the hyaline cartilage of the posterior cricoid lamina. They are slow-growing, present as submucosal masses, and display characteristic popcorn calcifications on CT.'),
    (v_topic_id, 'What is the primary treatment modality for a laryngeal chondrosarcoma?', '["Systemic chemotherapy", "High-dose radiation therapy", "Surgical excision (often with preservation of laryngeal function via partial laryngectomy or cricoid resection, as they are low-grade)", "Botox injections", "Observation only"]'::jsonb, 2, 'Chondrosarcomas are notoriously resistant to both radiation and chemotherapy. Surgical resection with negative margins is the only effective treatment.'),
    (v_topic_id, 'A 40-year-old African American female presents with mild hoarseness. Laryngoscopy reveals a small, firm, yellowish-pink, broadly sessile mass on the posterior aspect of the true vocal fold. Biopsy shows large polygonal cells with abundant granular eosinophilic cytoplasm that stain strongly positive for S-100 protein. What is the diagnosis?', '["Squamous cell carcinoma", "Granular Cell Tumor", "Vocal fold nodule", "Amyloidosis", "Chondroma"]'::jsonb, 1, 'Granular cell tumors are benign neoplasms derived from Schwann cells (hence the S-100 positivity). They often occur in the larynx or on the tongue.'),
    (v_topic_id, 'What deceptive histologic finding is frequently seen in the squamous epithelium OVERLYING a granular cell tumor, which can lead an inexperienced pathologist to misdiagnose it as squamous cell carcinoma?', '["Keratin pearls", "Pseudoepitheliomatous hyperplasia (PEH)", "Severe dysplasia", "Koilocytosis", "Apoptosis"]'::jsonb, 1, 'PEH is a reactive, wildly growing, but benign proliferation of the overlying epithelium caused by the underlying tumor. If a biopsy is too superficial, it mimics invasive SCC.'),
    (v_topic_id, 'Which of the following is a benign, vascular tumor of the larynx that presents with severe hoarseness and hemoptysis, and appears as a lobulated, "mulberry-like" red/purple mass on the vocal fold in an adult?', '["Squamous cell carcinoma", "Adult laryngeal hemangioma", "Reinke''s edema", "Vocal fold polyp", "Granular cell tumor"]'::jsonb, 1, 'Unlike infantile subglottic hemangiomas (which present with stridor and often resolve), adult laryngeal hemangiomas usually occur on the true vocal folds (glottis/supraglottis), do not regress, and often present with bleeding.'),
    (v_topic_id, 'A patient with neurofibromatosis type 1 (NF1) presents with hoarseness and a submucosal mass in the aryepiglottic fold. What benign nerve sheath tumor is most likely?', '["Granular cell tumor", "Plexiform neurofibroma", "Chondroma", "Paraganglioma", "Laryngocele"]'::jsonb, 1, 'NF1 patients are prone to developing neurofibromas anywhere along peripheral nerves, including the superior laryngeal nerve in the supraglottis.'),
    (v_topic_id, 'A highly vascular, pulsatile, submucosal mass is found in the supraglottis of a patient complaining of hoarseness and a feeling of a lump in the throat. Biopsy causes profuse bleeding. Histology shows "Zellballen" clusters of cells. What is the diagnosis?', '["Hemangioma", "Laryngeal Paraganglioma (Glomus tumor)", "Squamous cell carcinoma", "Granular cell tumor", "Chondroma"]'::jsonb, 1, 'Paragangliomas are rare, highly vascular neuroendocrine tumors. They arise from paraganglia associated with the superior laryngeal nerve. "Zellballen" (nests of chief cells) is the classic histologic finding.'),
    (v_topic_id, 'A patient with advanced Rheumatoid Arthritis (RA) complains of severe throat pain, hoarseness, and a feeling of a "lump" when swallowing. Laryngoscopy shows a red, swollen arytenoid that does not move well during phonation. What is the diagnosis?', '["Vocal fold paralysis", "Acute cricoarytenoid arthritis/ankylosis", "Squamous cell carcinoma", "LPR", "Croup"]'::jsonb, 1, 'The cricoarytenoid joint is a true diarthrodial synovial joint. RA can cause acute inflammation here, mimicking nerve paralysis but presenting with significant pain and eventually joint fixation (ankylosis).'),
    (v_topic_id, 'A patient with Relapsing Polychondritis presents to the ED with severe dyspnea and stridor. What is the primary mechanism of airway obstruction in this disease?', '["Vocal cord paralysis", "Autoimmune destruction of the cartilaginous tracheal rings and laryngeal framework, leading to airway collapse (tracheobronchomalacia)", "Massive swelling of the tongue", "A large obstructing polyp", "Acid reflux"]'::jsonb, 1, 'Relapsing polychondritis targets cartilage. Without the rigid support of the tracheal rings and cricoid, the airway collapses during respiration.'),
    (v_topic_id, 'A 35-year-old female presents with recurrent, severe subglottic stenosis. She also has a history of chronic sinusitis and recently coughed up blood. A c-ANCA titer is highly positive. What systemic disease is causing her laryngeal pathology?', '["Sarcoidosis", "Granulomatosis with Polyangiitis (Wegener''s granulomatosis)", "Lupus", "Rheumatoid Arthritis", "Tuberculosis"]'::jsonb, 1, 'GPA frequently involves the upper and lower respiratory tracts, and subglottic stenosis is a classic and notoriously difficult-to-manage manifestation.'),
    (v_topic_id, 'Which finding on direct laryngoscopy in a patient with Wegener''s (GPA) requires systemic medical treatment (immunosuppression) rather than just local surgical dilation?', '["A thin, mature web", "Active, red, inflamed, necrotizing granulomatous mucosa in the subglottis", "A normal airway", "A vocal fold nodule", "A laryngocele"]'::jsonb, 1, 'If the disease is "active" (inflamed and necrotizing), surgical manipulation will only worsen the scarring. The patient must be medically cooled down with steroids/immunosuppressants before surgical dilation of the stenosis.'),
    (v_topic_id, 'A patient with known sarcoidosis develops hoarseness and mild stridor. Laryngoscopy reveals a pale, massively thickened, "turban-like" epiglottis. What is the appropriate initial management?', '["Immediate total laryngectomy", "Systemic or intralesional corticosteroids to reduce the granulomatous inflammation", "Radiation therapy", "Antibiotics", "Tracheostomy as first line"]'::jsonb, 1, 'Laryngeal sarcoidosis usually responds well to steroids. Surgery (or tracheostomy) is reserved for severe airway obstruction unresponsive to medical therapy.'),
    (v_topic_id, 'A patient with a history of multiple myeloma presents with hoarseness. Laryngoscopy shows a smooth, firm, yellowish-orange submucosal mass in the false vocal fold. A biopsy stained with Congo red shows apple-green birefringence. What is the diagnosis?', '["Chondroma", "Granular cell tumor", "Laryngeal Amyloidosis", "Squamous cell carcinoma", "Vocal fold cyst"]'::jsonb, 2, 'Amyloidosis can be localized to the larynx or part of a systemic process (like multiple myeloma). It deposits extracellular protein, forming firm masses.'),
    (v_topic_id, 'What is the most common benign tumor of the larynx in adults?', '["Granular cell tumor", "Squamous papilloma (RRP)", "Chondroma", "Hemangioma", "Laryngocele"]'::jsonb, 1, 'Squamous papillomas (caused by HPV 6/11) are the most common benign neoplasms of the larynx in both children and adults.'),
    (v_topic_id, 'A 50-year-old male with a history of severe mucosal pemphigoid presents with hoarseness and dyspnea. What is a dreaded laryngeal complication of this blistering autoimmune disease?', '["Vocal fold paralysis", "Supraglottic and glottic scarring/webbing due to repeated mucosal blistering and healing", "Chondroma formation", "Cricoarytenoid arthritis", "Reinke''s edema"]'::jsonb, 1, 'Mucous membrane pemphigoid causes blisters that scar as they heal, leading to severe synechiae (webs) and airway stenosis in the larynx and pharynx.'),
    (v_topic_id, 'A patient requires an emergency surgical airway because of a massive facial trauma blocking oral intubation. The surgeon makes a vertical skin incision in the neck, palpates the gap between the thyroid cartilage and the cricoid cartilage, and makes a horizontal incision into the airway. What is this procedure called?', '["Standard tracheostomy", "Cricothyrotomy", "Total laryngectomy", "Thyroplasty", "Cordectomy"]'::jsonb, 1, 'A cricothyrotomy is the fastest and safest way to secure an emergency surgical airway because the cricothyroid membrane is superficial and relatively avascular.'),
    (v_topic_id, 'Why is a cricothyrotomy generally converted to a formal tracheostomy if the patient requires a surgical airway for more than a few days?', '["Because the cricothyrotomy tube falls out easily", "Prolonged intubation through the cricothyroid membrane causes severe inflammation and high risk of permanent subglottic stenosis", "Because a tracheostomy is faster to perform", "Because cricothyrotomy prevents talking forever", "Because it is required by law"]'::jsonb, 1, 'The cricothyroid membrane is located right at the subglottis/vocal cords. A tube here causes intense inflammation and subsequent subglottic scarring. A tracheostomy is placed lower (between tracheal rings 2 and 3) to protect the larynx.'),
    (v_topic_id, 'In a standard open tracheostomy, the tracheal incision or window is typically created between which tracheal rings?', '["Between the cricoid and the 1st ring", "Through the cricothyroid membrane", "Between the 2nd and 3rd (or 3rd and 4th) tracheal rings", "Between the 6th and 7th rings", "Through the thyroid cartilage"]'::jsonb, 2, 'This placement is low enough to avoid injuring the cricoid cartilage (preventing subglottic stenosis) but high enough to avoid slipping into the mediastinum.'),
    (v_topic_id, 'What is the most common early (intraoperative or immediate post-op) complication of a tracheostomy?', '["Tracheoinnominate fistula", "Subglottic stenosis", "Hemorrhage (e.g., from the anterior jugular veins or thyroid isthmus)", "Tracheoesophageal fistula", "Vocal cord paralysis"]'::jsonb, 2, 'Bleeding is the most common early complication. The thyroid isthmus must often be divided and ligated during the procedure.'),
    (v_topic_id, 'A patient with a tracheostomy for 3 weeks suddenly develops massive, pulsatile, bright red bleeding from the tracheostomy tube. What is the most likely, immediately life-threatening diagnosis?', '["Bleeding from the thyroid gland", "Tracheoinnominate artery fistula (TIF)", "Pulmonary embolism", "Ruptured vocal cord cyst", "Pneumothorax"]'::jsonb, 1, 'A TIF occurs when the tip of the tracheostomy tube erodes through the anterior tracheal wall and into the underlying innominate (brachiocephalic) artery. It is a catastrophic, often fatal emergency.'),
    (v_topic_id, 'What is the immediate temporizing maneuver for a suspected Tracheoinnominate Artery Fistula (TIF) while transporting the patient to the OR?', '["Administer IV antibiotics", "Hyperinflate the tracheostomy cuff to apply pressure, and if that fails, remove the tube and insert a finger into the stoma to compress the artery anteriorly against the sternum", "Pull the tube out and apply an oxygen mask", "Start chest compressions", "Give nebulized epinephrine"]'::jsonb, 1, 'The "Utley maneuver" (digital compression of the artery against the manubrium) is the only way to temporarily stop the torrential bleeding while rushing to the OR for sternotomy and artery ligation.'),
    (v_topic_id, 'A patient presents with a chronic cough and a feeling of food getting "stuck" in their throat. A barium swallow reveals a large posterior out-pouching of the pharyngeal mucosa emerging just above the cricopharyngeus muscle. What is this called?', '["Laryngocele", "Zenker''s diverticulum", "Thyroglossal duct cyst", "Branchial cleft cyst", "Esophageal web"]'::jsonb, 1, 'Zenker''s diverticulum occurs at Killian''s triangle (a weak spot between the thyropharyngeus and cricopharyngeus parts of the inferior constrictor). Food collects in the pouch, causing dysphagia, halitosis, and regurgitation of undigested food.'),
    (v_topic_id, 'What is the primary pathophysiology behind the formation of a Zenker''s diverticulum?', '["Viral infection", "Acid reflux burning a hole", "Dysfunction (failure to relax/spasm) of the cricopharyngeus muscle (upper esophageal sphincter) causing high intrapharyngeal pressure", "Cancer", "A congenital weak spot present at birth"]'::jsonb, 2, 'The uncoordinated, tight cricopharyngeus creates high pressure in the hypopharynx during swallowing, causing the mucosa to herniate backward.'),
    (v_topic_id, 'What is the definitive surgical treatment for a symptomatic Zenker''s diverticulum?', '["Surgical division (myotomy) of the cricopharyngeus muscle, often combined with stapling/excision of the diverticular pouch (can be done endoscopically or open)", "Botox injections alone forever", "Total laryngectomy", "Tracheostomy", "Dilation with a balloon"]'::jsonb, 0, 'The root cause (the tight muscle) MUST be cut (myotomy). If the pouch is just removed without a myotomy, it will immediately recur due to the high pressure.'),
    (v_topic_id, 'A patient complains of a chronic, persistent, dry cough that has lasted for months. Chest X-ray, pulmonary workup, and allergy testing are all negative. He reports a "tickle" in his throat. What laryngeal condition is a very common, often overlooked cause of chronic cough?', '["Laryngeal cancer", "Vocal fold paralysis", "Laryngopharyngeal Reflux (LPR) or Neurogenic cough (Sensory Neuropathy of the recurrent/superior laryngeal nerves)", "Spasmodic dysphonia", "Reinke''s edema"]'::jsonb, 2, 'LPR is a huge cause of chronic cough. Additionally, a post-viral sensory neuropathy can make the larynx hypersensitive, where even breathing cold air triggers a violent cough spasm.'),
    (v_topic_id, 'A patient with a suspected "neurogenic chronic cough" (sensory neuropathy of the larynx) is empirically treated with which class of medications if acid reflux and asthma have been ruled out?', '["Antibiotics", "Neuromodulators like Gabapentin or Amitriptyline", "High-dose oral steroids", "Inhaled bronchodilators", "Antifungals"]'::jsonb, 1, 'Neuromodulators dampen the hyperactive sensory firing of the superior laryngeal nerve, effectively suppressing the chronic "tickle" and cough reflex.'),
    (v_topic_id, 'A 2-year-old child presents with sudden onset of unilateral wheezing, a persistent cough, and a history of a choking episode while eating peanuts yesterday. What is the most likely diagnosis?', '["Croup", "Asthma", "Tracheobronchial foreign body aspiration", "Epiglottitis", "Laryngomalacia"]'::jsonb, 2, 'A history of a choking episode followed by asymmetric breath sounds (wheezing) in a toddler is a foreign body aspiration until proven otherwise.'),
    (v_topic_id, 'In a child with a suspected tracheobronchial foreign body, what is the definitive diagnostic and therapeutic procedure?', '["CT scan of the chest", "Rigid bronchoscopy under general anesthesia", "Flexible bedside bronchoscopy", "Albuterol nebulizer trial", "Observation"]'::jsonb, 1, 'Rigid bronchoscopy allows for ventilation while providing the large working channel necessary to safely grasp and remove the foreign object (like a peanut).'),
    (v_topic_id, 'Which mainstem bronchus is a foreign body more likely to enter in an adult, and why?', '["The left, because it is wider", "The left, because it is steeper", "The right, because it is wider, shorter, and more vertically oriented (steeper angle) than the left", "The right, because it is narrower", "They are exactly equal"]'::jsonb, 2, 'The right mainstem bronchus is a more direct continuation of the trachea.'),
    (v_topic_id, 'What type of foreign body is a true, time-sensitive medical emergency requiring immediate removal in the operating room, even if the airway is currently stable?', '["A piece of hot dog", "A plastic bead", "A button battery (e.g., lithium coin cell)", "A small pebble", "A piece of paper"]'::jsonb, 2, 'Button batteries conduct an electrical current when lodged in moist mucosa, generating hydroxide ions that cause severe, rapid liquefactive necrosis. A battery in the esophagus or airway can burn a hole through the wall into the aorta in less than 2 hours.'),
    (v_topic_id, 'A patient presents with a deep, penetrating knife wound to the anterior neck (Zone II). They are actively spitting up frothy blood and have a hoarse, breathy voice. What is the most appropriate management?', '["Send them home with antibiotics", "Perform a CT scan and wait", "Immediate surgical exploration in the OR and securing the airway via awake tracheostomy or fiberoptic intubation", "Apply a tight tourniquet around the neck", "Observe in the ICU"]'::jsonb, 2, 'Hard signs of airway injury (frothy hemoptysis, severe hoarseness, stridor) or vascular injury (active bleeding, expanding hematoma) following penetrating neck trauma mandate immediate surgical exploration in the OR.'),
    (v_topic_id, 'The anatomical zones of the neck are used to evaluate penetrating trauma. Which structures define the borders of Zone II?', '["From the clavicles to the cricoid cartilage", "From the cricoid cartilage to the angle of the mandible", "From the angle of the mandible to the base of the skull", "From the chin to the sternum", "The posterior neck only"]'::jsonb, 1, 'Zone II contains the majority of the larynx, the carotid sheath, and the esophagus. It is the most exposed but also the easiest to surgically explore.'),
    (v_topic_id, 'A patient undergoes a direct laryngoscopy with biopsy of a vocal fold lesion. In the recovery room, they develop sudden, severe stridor and difficulty breathing, but their voice is normal. What is the most likely cause?', '["Vocal fold paralysis", "Laryngospasm", "A massive stroke", "Heart attack", "Pneumonia"]'::jsonb, 1, 'Laryngospasm is a forceful, involuntary spasm of the true and false vocal folds, often triggered by blood or secretions irritating the glottis as the patient wakes from anesthesia. It causes acute stridor and airway obstruction.'),
    (v_topic_id, 'What is the immediate treatment for severe post-operative laryngospasm that does not break spontaneously?', '["Administer antibiotics", "Apply continuous positive airway pressure (CPAP/jaw thrust), and if it fails, administer a small dose of a fast-acting muscle relaxant (like succinylcholine) and re-intubate", "Perform an immediate tracheostomy", "Inject Botox", "Give high-dose steroids"]'::jsonb, 1, 'Breaking the spasm quickly is vital. Positive pressure (bag-mask ventilation) often overcomes it, but severe cases require paralysis to open the cords.'),
    (v_topic_id, 'A patient presents with a history of recurrent pneumonia. A swallowing study shows profound aspiration. The patient has a structurally normal larynx but absent sensation above the vocal folds. Which nerve is injured?', '["Recurrent laryngeal nerve", "Internal branch of the Superior Laryngeal Nerve (SLN)", "External branch of the Superior Laryngeal Nerve (SLN)", "Hypoglossal nerve", "Spinal accessory nerve"]'::jsonb, 1, 'The internal branch of the SLN provides all sensory innervation to the supraglottis. Without sensation, the patient cannot feel food or liquids pooling above the airway, leading to silent aspiration and pneumonia without triggering a cough reflex.'),
    (v_topic_id, 'What is the most common benign pediatric airway tumor?', '["Hemangioma", "Squamous papilloma (Recurrent Respiratory Papillomatosis)", "Chondroma", "Laryngocele", "Granular cell tumor"]'::jsonb, 1, 'RRP is the most common benign neoplasm of the pediatric airway, presenting with chronic hoarseness and progressing to stridor if not debulked.'),
    (v_topic_id, 'A patient with a history of prolonged intubation develops stridor. Endoscopy shows a web of scar tissue connecting the posterior aspects of the vocal folds. What is the anatomic structure that was primarily ulcerated to cause this?', '["The anterior commissure", "The epiglottis", "The mucosa overlying the vocal processes of the arytenoid cartilages", "The false vocal folds", "The cricothyroid membrane"]'::jsonb, 2, 'The endotracheal tube rests against the posterior glottis. Pressure necrosis here causes ulceration. When the tube is removed, the raw surfaces heal together, forming a posterior glottic web (synechia).'),
    (v_topic_id, 'Which of the following describes a "Type II" Thyroplasty?', '["Medialization of the vocal fold", "Lateralization of the vocal fold (used rarely for bilateral paralysis or spasmodic dysphonia to pull the cords apart)", "Shortening of the vocal fold", "Lengthening of the vocal fold", "Total removal of the vocal fold"]'::jsonb, 1, 'Type I pushes the cord in (medialization). Type II pulls the cords apart (lateralization). Type III shortens the cords (lowering pitch). Type IV lengthens the cords (raising pitch, used in gender-affirming voice surgery).')
